g=[[0]*28 for _ in range(28)]
# vertical lines cols 4,9,14,19,24 ; horizontal rows 4,9,14,19,24
colb=[[0,3],[5,8],[10,13],[15,18],[20,23]]  # full col blocks
rowb=[[0,3],[5,8],[10,13],[15,18],[20,23]]  # full row blocks
def fill(ri,ci,v):
    for r in range(*rowb[ri]) if False else range(rowb[ri][0],rowb[ri][1]+1):
        for c in range(colb[ci][0],colb[ci][1]+1):
            g[r][c]=v
# 2s: block cols 0 and 4, all full block rows
for ri in range(5):
    fill(ri,0,2); fill(ri,4,2)
# 3s: block rows 0 and 4, all full block cols
for ci in range(5):
    fill(0,ci,3); fill(4,ci,3)
# intersections -> 6
for ri in (0,4):
    fill(ri,0,6); fill(ri,4,6)
print('\n'.join(' '.join(map(str,r)) for r in g[:6]))

g=[[0]*28 for _ in range(28)]
bs=[(0,3),(5,8),(10,13),(15,18),(20,23)]  # full block spans, both axes
def fillb(r,c,v):
    for r_ in range(bs[r][0],bs[r][1]+1):
        for c_ in range(bs[c][0],bs[c][1]+1):
            g[r_][c_]=v
# 2 segments: row1 cols0-4 ; col0 rows1-3
for c in range(5): fillb(1,c,2)
for r in (1,2,3): fillb(r,0,2)
# 3 segment: col2 rows0-4
for r in range(5): fillb(r,2,3)
# overlap 2&3 -> 6
fillb(1,2,6)
for r in g[:24]:
    print(' '.join(map(str,r)))
print(len(g), len(g[0]))
